    string strBgColor = "";

    int n = dtbData.Rows.Count;
    int m = dtbData.Columns.Count;

    for (int i = n - 1; i >= 0; i--)
    {
        //if (i % 6 != 0) // xử lý để hiển buổi, ko cần tiết
        //    continue;

        DataRow drw = dtbData.Rows[i];
        strRow = "";

        for (int j = 1; j < m; j++)
        {
            if (j > 5 && lstWeek.IndexOf(j - 6) < 0) // nếu tính từ cột tuần rồi, mà tuần không có trong kế hoạch tổng thể thì bỏ qua
                continue;

            if (j == 3 || j == 5) // || j ==4 
                continue; // bo qua dong khong can day la LessionTime tho so

            string strColumn = drw[j].ToString().Replace("\r\n", "<br>");
            if (j > 5 && strColumn.Length < 3)
                strColumn = "&nbsp;";

            // nếu giống dòng trước thì là merge                                                            
            if (i > 0 && (i % 6 != 0 || j < 6) && drw[j].ToString() == dtbData.Rows[i - 1][j].ToString()) // còn giống và không fai đầu buổi
                rowspan[j] = rowspan[j] + 1; // tăng mergce, không cộng thêm cột nào
            else // nếu không còn giống nữa thì dừng
            {
                if (rowspan[j] > 1 || strColumn != "&nbsp;")
