                            strBgColor = " style='background-color:#f9bad4' "; // màu hồng
                        else if (strColumn.Contains("(BÁO NGHỈ)"))
                            strBgColor = " style='background-color:#FF0000' "; // màu đỏ
                        else if (strColumn.Contains("(Dạy bù)"))
                            strBgColor = " style='background-color:#ffbd02' "; // màu cam

                    }
                    else
                        strBgColor = "";

                    strRow += "<td " + strBgColor + " rowspan='" + rowspan[j].ToString() + "'>" + strColumn + "</td>";
                    rowspan[j] = 1;
                }
                else
                    strRow += "<td>" + strColumn + "</td>";
            }
        }
        strRow = "<tr>" + strRow + "</tr>\r\n";
        str = strRow + str;
    }

    string strHead = "<tr style='background-color:#cccccc; font-weight:bold'><td rowspan='3'>Thứ</td> <td rowspan='3'>Buổi</td><td rowspan='3'>Tiết</td>";
    string strHeadDateFrom = "<tr style='background-color:#cccccc; font-weight:bold'>";
    string strHeadDateTo = "<tr style='background-color:#cccccc; font-weight:bold'>";
    for (int j = 1; j <= 54; j++)
    {
        if (lstWeek.IndexOf(j - 1) < 0) // nếu tuần không có trong kế hoạch tổng thể thì bỏ qua
            continue;
        strHead += "<td>Tuần " + j.ToString() + "</td>";
        strHeadDateFrom += "<td>" + dtmFromDate.AddDays((j - 1) * 7).ToString("dd/MM") + "</td>";
        strHeadDateTo += "<td>" + dtmFromDate.AddDays((j - 1) * 7 + 6).ToString("dd/MM") + "</td>";

    }
    strHead += "</tr>";
    strHeadDateFrom += "</tr>";
    strHeadDateTo += "</tr>";

    str = "<table>" + strHead + strHeadDateFrom + strHeadDateTo + str + "</table>";



    lblTitle.Text = "LỊCH GIẢNG VIÊN " + uTeacher.TeacherName +  " _ Học  kì " + uYearSemester1.Semester + " _  Niên học " + uYearSemester1.YearText ;
    lblContent.Text = str;            
}

